  ('Computer Science', 'AQA', 'gcse', '3.1', 'Fundamentals of Algorithms', 'How does a binary search work?', 'It repeatedly compares the target with the middle item of a sorted list and discards the half that can''t contain it.', 14),
  ('Computer Science', 'AQA', 'gcse', '3.1', 'Fundamentals of Algorithms', 'What is the precondition for binary search?', 'The list must be sorted.', 15),
