  ('Computer Science', 'AQA', 'gcse', '3.2', 'Programming', 'What is defensive design?', 'Designing programs to anticipate misuse and handle errors so they don''t crash.', 23),
  ('Computer Science', 'AQA', 'gcse', '3.2', 'Programming', 'What is input validation?', 'Checking that data entered is sensible and reasonable before it is processed.', 24),
