  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is the base of binary, denary and hexadecimal?', 'Binary is base 2, denary is base 10, and hexadecimal is base 16.', 1),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Convert binary 11010110 to denary.', '128 + 64 + 16 + 4 + 2 = 214.', 2),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Convert denary 200 to binary.', '11001000.', 3),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Convert binary 10111110 to hexadecimal.', 'Split into nibbles 1011 and 1110: B and E, so BE.', 4),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Convert hexadecimal A7 to binary.', 'A = 1010, 7 = 0111, so 10100111.', 5),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Convert hexadecimal 3C to denary.', '3 × 16 + 12 = 60.', 6),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What are the hex digits for 10 to 15?', 'A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.', 7),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Add binary 0101 + 0011.', '1000 (5 + 3 = 8).', 8),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is overflow in binary addition?', 'When the result needs more bits than are available, so the extra bit is lost.', 9),
