  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What does a binary right shift by 1 do?', 'Divides the number by 2 (losing any remainder).', 11),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Shift 00010110 left by 2 places. What is the result?', '01011000 (22 × 4 = 88).', 12),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is the largest denary number that can be stored in 8 bits?', '255.', 13),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'How many different values can be represented with n bits?', '2ⁿ.', 14),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is a kibibyte?', '1024 bytes.', 15),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'How many bits are in a kilobyte (1000 bytes)?', '8000 bits.', 16),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is ASCII?', 'A 7-bit character set representing 128 characters, including English letters, digits and symbols.', 17),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is Unicode?', 'A character set using more bits to represent characters from many languages and symbols, including emoji.', 18),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Why was Unicode developed?', 'ASCII couldn''t represent characters from other languages.', 19),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'In ASCII, if ''A'' is 65, what is ''D''?', '68 (character codes are sequential).', 20),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is a pixel?', 'The smallest element of a bitmap image, a single dot of colour.', 21),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is image resolution?', 'The number of pixels in an image, often given as width × height.', 22),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'How do you calculate the file size of an image?', 'Width × height × colour depth (in bits).', 23),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'Calculate the size of a 100 × 50 image with a colour depth of 8 bits.', '100 × 50 × 8 = 40,000 bits = 5,000 bytes.', 24),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is metadata in an image?', 'Extra data stored with the image, such as width, height and colour depth.', 25),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is sample rate?', 'The number of sound samples taken per second, measured in hertz.', 26),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is sample resolution?', 'The number of bits used to store each sound sample.', 27),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'How do you calculate the file size of a sound file?', 'Sample rate × sample resolution × duration (seconds).', 28),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is run-length encoding (RLE)?', 'A lossless compression method that stores repeated data as a value and a count, e.g. AAAAA becomes 5A.', 29),
  ('Computer Science', 'AQA', 'gcse', '3.3', 'Fundamentals of Data Representation', 'What is Huffman coding?', 'A lossless compression method that gives shorter binary codes to more frequent characters, using a tree.', 30),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is the purpose of the CPU?', 'To fetch, decode and execute instructions, processing data to run programs.', 1),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does the fetch–decode–execute cycle do?', 'The CPU repeatedly fetches an instruction from memory, decodes it to work out what to do, then executes it.', 2),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is the Arithmetic Logic Unit (ALU)?', 'The part of the CPU that performs calculations and logical comparisons.', 3),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is the Control Unit (CU)?', 'The part of the CPU that decodes instructions and sends control signals to coordinate the other components.', 4),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is cache?', 'Very fast memory inside or close to the CPU that stores frequently used instructions and data.', 5),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What are registers?', 'Tiny, very fast storage locations inside the CPU that hold data and instructions currently being processed.', 6),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does the Program Counter (PC) store?', 'The address of the next instruction to be fetched.', 7),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does the Memory Address Register (MAR) store?', 'The address in memory of the data or instruction being fetched or stored.', 8),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does the Memory Data Register (MDR) store?', 'The data or instruction that has been fetched from memory or is about to be written to memory.', 9),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does the accumulator store?', 'The results of calculations carried out by the ALU.', 10),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is primary storage?', 'Memory that the CPU can access directly, such as RAM and ROM.', 11),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is RAM?', 'Random access memory: volatile memory that stores data, programs and the operating system currently in use.', 12),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does volatile mean?', 'The contents are lost when the power is turned off.', 13),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is ROM?', 'Read-only memory: non-volatile memory that stores the boot-up instructions (BIOS).', 14),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is the difference between RAM and ROM?', 'RAM is volatile and can be written to; ROM is non-volatile and usually read-only.', 15),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'Why do computers need primary storage?', 'To hold data and instructions the CPU needs quickly, because secondary storage is too slow.', 16),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is Boolean logic?', 'Logic using the values TRUE (1) and FALSE (0).', 17),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does an AND gate do?', 'Outputs 1 only if both inputs are 1.', 18),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does an OR gate do?', 'Outputs 1 if at least one input is 1.', 19),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What does a NOT gate do?', 'Outputs the opposite of the input.', 20),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'Draw the truth table for AND.', '0 AND 0 = 0; 0 AND 1 = 0; 1 AND 0 = 0; 1 AND 1 = 1.', 21),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'Draw the truth table for OR.', '0 OR 0 = 0; 0 OR 1 = 1; 1 OR 0 = 1; 1 OR 1 = 1.', 22),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'Draw the truth table for NOT.', 'NOT 0 = 1; NOT 1 = 0.', 23),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is a high-level language?', 'A programming language close to human language, e.g. Python or Java.', 24),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is a low-level language?', 'A language close to machine code, e.g. assembly language or machine code.', 25),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'Give an advantage of high-level languages.', 'They are easier to read, write and debug, and are portable between computers.', 26),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'Give an advantage of low-level languages.', 'They give direct control over hardware and can be more efficient in speed and memory.', 27),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is machine code?', 'Binary instructions that the CPU can execute directly.', 28),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is assembly language?', 'A low-level language that uses mnemonics (e.g. ADD, LDA) to represent machine code instructions.', 29),
  ('Computer Science', 'AQA', 'gcse', '3.4', 'Computer Systems', 'What is a translator?', 'A program that converts source code into machine code.', 30),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a network?', 'Two or more computers connected together to share data and resources.', 1),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a LAN?', 'A local area network covering a small geographical area, such as a school, using its own hardware.', 2),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a WAN?', 'A wide area network covering a large geographical area, often using third-party infrastructure; the internet is the largest WAN.', 3),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What factors affect network performance?', 'Bandwidth, number of users, transmission media, errors, and interference.', 4),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is bandwidth?', 'The amount of data that can be transmitted per second.', 5),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a client–server network?', 'A network where servers provide services and resources to client computers.', 6),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a peer-to-peer network?', 'A network where all computers have equal status and share resources directly with each other.', 7),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'Give an advantage of a client–server network.', 'Centralised security, backups and file management.', 8),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'Give an advantage of a peer-to-peer network.', 'Cheap and easy to set up, with no dependence on a server.', 9),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a wireless access point (WAP)?', 'A device that allows wireless devices to connect to a wired network.', 10),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a router?', 'A device that forwards data packets between networks, e.g. between a LAN and the internet.', 11),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a switch?', 'A device that connects devices on a LAN and sends data only to the intended device using MAC addresses.', 12),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a NIC?', 'A network interface card (controller), which allows a device to connect to a network.', 13),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is the internet?', 'A worldwide collection of interconnected networks.', 14),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is DNS?', 'The Domain Name System, which translates domain names (e.g. bbc.co.uk) into IP addresses.', 15),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is hosting?', 'Storing websites or files on a server connected to the internet so others can access them.', 16),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is the cloud?', 'Remote servers accessed over the internet to store data and run software.', 17),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'Give an advantage and disadvantage of the cloud.', 'Advantage: access from anywhere, no need for local storage. Disadvantage: needs internet access and raises security concerns.', 18),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a star topology?', 'All devices connect to a central switch.', 19),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a mesh topology?', 'Devices are connected to many other devices, so data has several possible routes.', 20),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'Give an advantage of a star topology.', 'If one cable fails, the other devices are unaffected, and it is easy to add devices.', 21),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'Give an advantage of a mesh topology.', 'No single point of failure; data can take another route if a connection fails.', 22),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is Wi-Fi?', 'A wireless networking standard using radio waves to connect devices to a network.', 23),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is Ethernet?', 'A wired networking standard for connecting devices in a LAN.', 24),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is an IP address?', 'A unique address given to each device on a network, used to route data.', 25),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a MAC address?', 'A unique, permanent hardware address assigned to a network interface.', 26),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is a protocol?', 'A set of rules for how data is transmitted across a network.', 27),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What are TCP/IP and HTTP used for?', 'TCP/IP: sending data across the internet in packets. HTTP: requesting and transferring web pages.', 28),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is HTTPS?', 'A secure version of HTTP that encrypts data between browser and server.', 29),
  ('Computer Science', 'AQA', 'gcse', '3.5', 'Fundamentals of Computer Networks', 'What is the concept of layers in networking?', 'Protocols are divided into layers, each handling a specific part of communication, making development and troubleshooting easier.', 30),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is malware?', 'Malicious software designed to damage, disrupt or gain unauthorised access to computer systems.', 1),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a virus?', 'Malware that attaches itself to files and spreads when those files are copied or opened.', 2),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a worm?', 'Malware that replicates itself and spreads across networks without user action.', 3),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a Trojan?', 'Malware disguised as legitimate software.', 4),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is ransomware?', 'Malware that encrypts a user''s files and demands payment for their release.', 5),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is spyware?', 'Malware that secretly monitors user activity and collects information.', 6),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is social engineering?', 'Manipulating people into giving away confidential information.', 7),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is phishing?', 'Sending fake emails or messages that appear to be from a trusted source to trick people into revealing personal information.', 8),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is shouldering?', 'Watching someone enter a password or PIN over their shoulder.', 9),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a brute-force attack?', 'Trying every possible combination of characters to guess a password.', 10),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a denial of service (DoS) attack?', 'Flooding a server with requests so it can''t respond to genuine users.', 11),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is data interception?', 'Capturing data as it travels across a network, e.g. using packet sniffers.', 12),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is SQL injection?', 'Entering malicious SQL code into an input field to access or change a database.', 13),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is penetration testing?', 'Authorised simulated attacks on a system to find vulnerabilities.', 14),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is anti-malware software?', 'Software that detects, prevents and removes malware.', 15),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a firewall?', 'Hardware or software that monitors network traffic and blocks unauthorised access.', 16),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What are user access levels?', 'Permissions that control which files and resources different users can access.', 17),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'Why are strong passwords important?', 'They are harder to guess or brute-force, protecting accounts from unauthorised access.', 18),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What makes a strong password?', 'A long password mixing upper and lower case letters, numbers and symbols, not based on personal information.', 19),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is encryption?', 'Scrambling data using a key so it can only be read by someone with the correct key.', 20),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is physical security?', 'Protecting hardware from theft or damage, e.g. locks, CCTV and security guards.', 21),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is two-factor authentication?', 'Requiring two forms of verification, such as a password and a code sent to a phone.', 22),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'How can SQL injection be prevented?', 'Validating input and using parameterised queries.', 23),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'How can phishing be prevented?', 'User training, spam filters, and checking email addresses and links before clicking.', 24),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'How can brute-force attacks be prevented?', 'Strong passwords, account lockouts after failed attempts, and CAPTCHAs.', 25),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'How can DoS attacks be reduced?', 'Firewalls, traffic filtering, and increasing server capacity.', 26),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a vulnerability?', 'A weakness in a system that can be exploited by an attacker.', 27),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'Why do organisations need network policies?', 'To define acceptable use, security procedures and responsibilities, reducing risks.', 28),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is a backup?', 'A copy of data stored separately so it can be restored if the original is lost or damaged.', 29),
  ('Computer Science', 'AQA', 'gcse', '3.6', 'Cyber Security', 'What is the difference between hackers and malware?', 'Hackers are people who gain unauthorised access; malware is software used to cause harm.', 30),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a database?', 'An organised, structured collection of data that can be easily searched and managed.', 1),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a relational database?', 'A database that stores data in linked tables to reduce data redundancy.', 2),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a table?', 'A collection of records about one type of entity, e.g. Students.', 3),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a record?', 'A row in a table, containing data about one item.', 4),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a field?', 'A column in a table, containing one piece of data about each record.', 5),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a primary key?', 'A field that uniquely identifies each record in a table.', 6),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a foreign key?', 'A field in one table that is the primary key in another table, used to link them.', 7),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is data redundancy?', 'Unnecessary duplication of data.', 8),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is data inconsistency?', 'When the same data has different values in different places.', 9),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'How do relational databases reduce redundancy?', 'Data is stored once in separate linked tables, rather than repeated.', 10),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does SELECT do in SQL?', 'Retrieves specified fields from a table.', 11),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does FROM do in SQL?', 'Specifies which table(s) to retrieve data from.', 12),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does WHERE do in SQL?', 'Filters records based on a condition.', 13),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does ORDER BY do in SQL?', 'Sorts the results in ascending (ASC) or descending (DESC) order.', 14),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'Write SQL to select the name and age of students older than 15.', 'SELECT Name, Age FROM Students WHERE Age > 15;', 15),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'Write SQL to select all fields from Products ordered by price, highest first.', 'SELECT * FROM Products ORDER BY Price DESC;', 16),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does * mean in SQL?', 'All fields.', 17),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does INSERT INTO do in SQL?', 'Adds a new record to a table.', 18),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'Write SQL to add a student called Ali, aged 16.', 'INSERT INTO Students (Name, Age) VALUES (''Ali'', 16);', 19),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does UPDATE do in SQL?', 'Changes existing data in a table.', 20),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'Write SQL to change the age of student ID 5 to 17.', 'UPDATE Students SET Age = 17 WHERE StudentID = 5;', 21),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What does DELETE do in SQL?', 'Removes records from a table.', 22),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'Write SQL to delete students in year 13.', 'DELETE FROM Students WHERE Year = 13;', 23),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What happens if you omit WHERE in an UPDATE or DELETE?', 'Every record in the table is updated or deleted.', 24),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'How do you combine conditions in SQL?', 'Using AND and OR, e.g. WHERE Age > 15 AND Year = 11.', 25),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'How do you select data from two tables in SQL?', 'List both tables and link them with a condition on the foreign key, e.g. WHERE Orders.CustomerID = Customers.CustomerID.', 26),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a query?', 'A request to retrieve or change data in a database.', 27),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is a data type in a database field?', 'The type of data stored, e.g. text, integer, real, date or Boolean.', 28),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'Why is a text field used for phone numbers?', 'They can start with 0 and contain spaces or symbols, and aren''t used in calculations.', 29),
  ('Computer Science', 'AQA', 'gcse', '3.7', 'Relational Databases and SQL', 'What is an entity?', 'A thing about which data is stored, e.g. a student, product or order.', 30),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is the Data Protection Act 2018?', 'UK law (implementing GDPR) controlling how personal data is collected, stored and used.', 1),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'Give three principles of data protection.', 'Data must be used fairly and lawfully, kept secure, accurate, up to date, and not kept longer than necessary.', 2),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is the Computer Misuse Act 1990?', 'UK law making unauthorised access to computer material and modification of data illegal.', 3),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What are the three offences in the Computer Misuse Act?', 'Unauthorised access; unauthorised access with intent to commit further crimes; unauthorised modification of data.', 4),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is the Copyright, Designs and Patents Act 1988?', 'UK law protecting intellectual property, such as software, music and images, from being copied without permission.', 5),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is software licensing?', 'Legal permission to use software, which sets out how it can be used.', 6),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is open-source software?', 'Software whose source code is freely available to view, modify and distribute.', 7),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is proprietary software?', 'Software whose source code is kept secret, usually sold with a licence restricting use.', 8),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'Give an advantage of open-source software.', 'It is usually free and can be modified to suit users'' needs.', 9),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'Give an advantage of proprietary software.', 'It usually comes with professional support and regular updates.', 10),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is an ethical issue?', 'An issue about what is morally right or wrong.', 11),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is a legal issue?', 'An issue about what is permitted or forbidden by law.', 12),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is a cultural issue?', 'An issue about how technology affects society, traditions and ways of life.', 13),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is an environmental issue?', 'An issue about the impact of technology on the environment.', 14),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is the digital divide?', 'The gap between people who have access to technology and the internet and those who don''t.', 15),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What causes the digital divide?', 'Cost, location (rural areas), age, disability and lack of skills.', 16),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is e-waste?', 'Discarded electronic devices, which contain toxic materials and are often not recycled properly.', 17),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'How does computing affect the environment?', 'Energy use, mining for raw materials, and e-waste; but it can also reduce travel and paper use.', 18),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What are privacy concerns with technology?', 'Personal data collection, tracking, surveillance and data breaches.', 19),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What are the ethical issues of artificial intelligence?', 'Bias, job losses, accountability for decisions, and privacy.', 20),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'How has technology affected employment?', 'It has created new jobs (e.g. in IT) but replaced some jobs through automation.', 21),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is cyberbullying?', 'Using technology to harass, threaten or embarrass someone.', 22),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What are the health issues of computer use?', 'Eye strain, repetitive strain injury, back problems and reduced physical activity.', 23),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is a stakeholder?', 'A person or group affected by a technology or decision.', 24),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is censorship?', 'Restricting access to information, e.g. governments blocking websites.', 25),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is the Freedom of Information Act 2000?', 'UK law giving the public the right to request information held by public authorities.', 26),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What are the benefits of technology to society?', 'Improved communication, access to information, healthcare advances and efficiency.', 27),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What are self-driving cars'' ethical issues?', 'Responsibility for accidents, decisions in unavoidable collisions, and job losses for drivers.', 28),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is surveillance?', 'Monitoring people''s activities, e.g. CCTV and tracking online activity.', 29),
  ('Computer Science', 'AQA', 'gcse', '3.8', 'Ethical, Legal and Environmental Impacts', 'What is a Creative Commons licence?', 'A licence that allows creators to let others share and use their work under certain conditions.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Computer Science' AND exam_board = 'AQA' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
